modules[S(441)] = function()
return function(import)
local Players = game:GetService(S(271))
local getCurrentPlot = import(S(438))
local getPlotParts = import(S(367))
local teleport = import(S(77))
local click = import(S(324))
local log = import(S(37))
local CHECK_INTERVAL = 3
local MIN_ITEMS_TO_COLLECT = 100
local function getChestFrame()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(235))
    local mineGui = playerGui and playerGui:FindFirstChild(S(322))
    return mineGui and mineGui:FindFirstChild(S(156))
end
local function getTakeButton(chestFrame)
    local content = chestFrame and chestFrame:FindFirstChild(S(339))
    local actions = content and content:FindFirstChild(S(175))
    return actions and actions:FindFirstChild(S(8))
end
local function getItemCount(chestFrame)
    local content = chestFrame:FindFirstChild(S(397))
    local progress = content and content:FindFirstChild(S(80))
    local label = progress and progress:FindFirstChild(S(394))
    local text = label and label.Text or S(124)
    local digits = text:gsub(S(366), S(395)):match(S(33))
    return tonumber(digits)
end
local function clickButton(button)
    local ok, err = click.Real(button)
    if not ok then
        log(S(120) .. button.Name .. S(305) .. tostring(err))
    end
    return ok
end
local function getChestPrompt()
    local plot = getCurrentPlot()
    local parts = plot and getPlotParts(plot)
    return parts and parts.Chest and parts.Chest:FindFirstChildWhichIsA(S(28), true)
end
local autoChest = {}
local enabled = false
local busy = false
local lastAttempt = 0
function autoChest.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    if not enabled then
        if not busy then
            teleport.Return()
        end
        log(S(70))
    else
        lastAttempt = 0
        log(S(400) .. MIN_ITEMS_TO_COLLECT .. S(237))
    end
end
function autoChest.IsEnabled()
    return enabled
end
function autoChest.IsBusy()
    return busy
end
local function runJob()
    busy = true
    local prompt = getChestPrompt()
    if not prompt then
        busy = false
        return
    end
    teleport.To(prompt.Parent)
    local ok, err = pcall(function()
        fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
    end)
    if not ok then
        log(S(282) .. tostring(err))
        teleport.Return()
        busy = false
        return
    end
    task.wait(0.8)
    if not enabled then
        teleport.Return()
        busy = false
        return
    end
    local chestFrame = getChestFrame()
    if not (chestFrame and chestFrame.Visible) then
        log(S(405))
        teleport.Return()
        busy = false
        return
    end
    local count = getItemCount(chestFrame)
    if count and count < MIN_ITEMS_TO_COLLECT then
        log(S(488) .. count .. S(344))
        local closeButton = chestFrame:FindFirstChild(S(85))
        if closeButton then
            clickButton(closeButton)
        end
        teleport.Return()
        busy = false
        return
    end
    local takeButton = getTakeButton(chestFrame)
    if takeButton then
        clickButton(takeButton)
        task.wait(0.6)
        local after = getItemCount(chestFrame)
        if after and count and after < count then
            log(S(123) .. count .. S(433) .. after .. S(220))
        else
            log(S(186) .. tostring(count)
                .. S(236) .. tostring(after) .. S(357))
        end
    end
    teleport.Return()
    busy = false
end
function autoChest.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < CHECK_INTERVAL then
        return
    end
    lastAttempt = now
    task.spawn(runJob)
end
return autoChest
end
end
