local getPlotParts = import(S(95))
local log = import(S(221))
local FIRE_INTERVAL = 0.2
local function findClickDetector(instance)
    return instance:FindFirstChildWhichIsA(S(267), true)
end
local autoMine = {}
local enabled = false
local lastFire = 0
function autoMine.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    log(S(272) .. (enabled and S(467) or S(210)))
end
function autoMine.IsEnabled()
    return enabled
end
function autoMine.Step()
    if not enabled then
        return
    end
    local now = tick()
    if now - lastFire < FIRE_INTERVAL then
        return
    end
    lastFire = now
    local plot = getCurrentPlot()
    if not plot then
        return
    end
    local parts = getPlotParts(plot)
    if not parts.Nodes then
        return
    end
    for _, node in ipairs(parts.Nodes:GetChildren()) do
        local detector = findClickDetector(node)
        if detector then
            fireclickdetector(detector)
        end
    end
end
return autoMine
end
end
modules[S(422)] = function()
return function(import)
local Players = game:GetService(S(481))
local getCurrentPlot = import(S(331))
local getPlotParts = import(S(464))
local log = import(S(275))
local FIRE_INTERVAL = 1
local function findHolderPrompt(holder)
    local pad = holder:FindFirstChild(S(76))
    return pad and pad:FindFirstChildWhichIsA(S(419), true)
end
local function isHolderEmpty(prompt)
    return prompt ~= nil and prompt.ObjectText == S(431)
end
local autoPlace = {}
local enabled = false
local lastFire = 0
local lastReason = nil
local function reason(text)
    if text ~= lastReason then
        log(S(421) .. text)
        lastReason = text
    end
end
function autoPlace.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    lastReason = nil
    log(S(150) .. (enabled and S(1) or S(66)))
end
function autoPlace.IsEnabled()
    return enabled
end
function autoPlace.Step()
    if not enabled then
        return
    end
    local now = tick()
    if now - lastFire < FIRE_INTERVAL then
        return
    end
    lastFire = now
    local player = Players.LocalPlayer
    local character = player.Character
    local backpack = player:FindFirstChild(S(191))
    if not character or not backpack then
        reason(S(83))
        return
    end
    local humanoid = character:FindFirstChildOfClass(S(110))
    local tool = backpack:FindFirstChildWhichIsA(S(161))
    if not humanoid then
        reason(S(428))
        return
    end
    if not tool then
        reason(S(350))
        return
    end
    local plot = getCurrentPlot()
    if not plot then
        reason(S(214))
        return
    end
    local parts = getPlotParts(plot)
    if not parts.Holders then
        reason(S(4))
        return
    end
    local placed = false
    for _, holder in ipairs(parts.Holders:GetChildren()) do
        local prompt = findHolderPrompt(holder)
        if isHolderEmpty(prompt) then
            humanoid:EquipTool(tool)
            local ok, err = pcall(function()
                fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
            end)
            if ok then
                log(S(270) .. tool.Name .. S(112) .. holder.Name)
            else
                log(S(341) .. tostring(err))
            end
            placed = true
            break
        end
    end
    if not placed then
        reason(S(158) .. #parts.Holders:GetChildren() .. S(343))
    else
        lastReason = nil
    end
end
return autoPlace
end
end
