return function(import)
local Players = game:GetService(S(439))
local Workspace = game:GetService(S(309))
local teleport = import(S(335))
local click = import(S(470))
local log = import(S(353))
local CHECK_INTERVAL = 3
local NOTHING_SELLABLE_COOLDOWN = 60
local function getSellFrame()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(225))
    local mineGui = playerGui and playerGui:FindFirstChild(S(15))
    return mineGui and mineGui:FindFirstChild(S(296))
end
local function labelText(button)
    local content = button:FindFirstChild(S(90))
    local label = content and content:FindFirstChild(S(294))
    return label and label.Text or S(462)
end
local function countCards(sellFrame)
    local content = sellFrame:FindFirstChild(S(106))
    local scroll = content and content:FindFirstChild(S(318))
    if not scroll then
        return 0
    end
    local count = 0
    for _, child in ipairs(scroll:GetChildren()) do
        if child.Name == S(174) then
            count = count + 1
        end
    end
    return count
end
local function clickButton(button)
    local ok, err = click.Real(button)
    if not ok then
        log(S(73) .. button.Name .. S(68) .. tostring(err))
    end
    return ok
end
local function getSellStandPromptPart()
    local sellStand = Workspace:FindFirstChild(S(391))
    local prompt = sellStand and sellStand:FindFirstChildWhichIsA(S(266), true)
    return prompt, prompt and prompt.Parent
end
local autoSell = {}
local enabled = false
local busy = false
local lastAttempt = 0
function autoSell.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    if not enabled then
        if not busy then
            teleport.Return()
        end
        log(S(207))
    else
        lastAttempt = 0
        log(S(466))
    end
end
function autoSell.IsEnabled()
    return enabled
end
function autoSell.IsBusy()
    return busy
end
local function runJob()
    busy = true
    local prompt, promptPart = getSellStandPromptPart()
    if not (prompt and promptPart) then
        busy = false
        return
    end
    teleport.To(promptPart)
    local ok, err = pcall(function()
        fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
    end)
    if not ok then
        log(S(250) .. tostring(err))
        teleport.Return()
        busy = false
        return
    end
    task.wait(0.8)
    if not enabled then
        teleport.Return()
        busy = false
        return
    end
    local sellFrame = getSellFrame()
    if not (sellFrame and sellFrame.Visible) then
        log(S(330))
        teleport.Return()
        busy = false
        return
    end
    local cardCount = countCards(sellFrame)
    if cardCount == 0 then
        log(S(115))
        local closeButton = sellFrame:FindFirstChild(S(420))
        if closeButton then
            clickButton(closeButton)
        end
        teleport.Return()
        busy = false
        return
    end
    local content = sellFrame:FindFirstChild(S(246))
    local selectAllButton = content and content:FindFirstChild(S(451))
    local sellButton = content and content:FindFirstChild(S(187))
    if selectAllButton and labelText(selectAllButton) == S(413) then
        clickButton(selectAllButton)
        log(S(121) .. cardCount .. S(393))
    end
    local sawLabel = nil
    for _ = 1, 5 do
        task.wait(0.3)
        sawLabel = sellButton and labelText(sellButton) or nil
        if sawLabel and sawLabel:find(S(31), 1, true) then
            break
        end
    end
    if sawLabel and sawLabel:find(S(388), 1, true) then
        clickButton(sellButton)
        log(S(141))
    else
        lastAttempt = tick() + NOTHING_SELLABLE_COOLDOWN - CHECK_INTERVAL
        local closeButton = sellFrame:FindFirstChild(S(485))
        if closeButton then
            clickButton(closeButton)
        end
        log(S(14) .. cardCount .. S(253)
            .. tostring(sawLabel) .. S(338) .. NOTHING_SELLABLE_COOLDOWN .. S(416))
    end
    task.wait(0.5)
    teleport.Return()
    busy = false
end
function autoSell.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < CHECK_INTERVAL then
        return
    end
    lastAttempt = now
    task.spawn(runJob)
end
return autoSell
end
end
