local function dumpInstance(instance, log, indent)
    indent = indent or S(35)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(486) .. child.Name .. S(251)
        if child:IsA(S(345)) then
            line = line .. string.format(
                S(65),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(316)) then
            line = line .. string.format(S(234), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(356)) or child:IsA(S(461)) then
            line = line .. S(23)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(469) .. attrName .. S(307) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(243))
    end
end
return dumpInstance
end
